+  if (variant != 1 &&
+      tiled_supported(a, a_scale, weight, weight_scale, grouped, k)) {
+    const TiledArgs args{reinterpret_cast<const uint8_t*>(a.data_ptr()),
+                         a_scale.data_ptr(),
+                         reinterpret_cast<const uint8_t*>(weight.data_ptr()),
+                         weight_scale.data_ptr(),
+                         output.data_ptr(),
