+  }
+  const dim3 grid((m + 15) / 16, (n + 31) / 32, groups);
+  AT_DISPATCH_FLOATING_TYPES_AND2(
+      at::kHalf, at::kBFloat16, output.scalar_type(), "block32_scaled_mm", [&] {
