+                  output.scalar_type() == at::kBFloat16 && output.dim() == 3 &&
+                  output.size(0) == seq_lens.numel() && output.size(2) == 512 &&
+                  output.stride(2) == 1 && offset >= 0 &&
+                  offset <= output.size(1),
