+template <bool FUSE_SILU_AND_MUL>
+__device__ __forceinline__ int64_t compute_input_group_start_offset(
+    int expert_idx, int64_t token_idx, int hidden_dim_group_idx,
+    int hidden_size, int num_tokens_per_expert, int group_size) {
+  return static_cast<int64_t>(expert_idx) * num_tokens_per_expert *
+             hidden_size * (FUSE_SILU_AND_MUL ? 2 : 1) +
+         static_cast<int64_t>(token_idx) * hidden_size *
+             (FUSE_SILU_AND_MUL ? 2 : 1) +
+         static_cast<int64_t>(hidden_dim_group_idx) * group_size;
+}
